import texturaTokens from "@theme/tokens/textura";

import { createThemeWithoutDefaultMerge } from "../utils/create-theme-without-default";

export const getDefaultTheme = (options = { useCSSVariables: true }) => {
  let theme = createThemeWithoutDefaultMerge({
    /*
      This value is enabled by default and enables the use of CSS variables for theming.
      These CSS variables will cascade down to all components. If you would like not not 
      make use of CSS variables, set this value to false.

      Naming convention for CSS variables follows this pattern:
        theme.color.background.default -> --ntx-palette-background-color
    */
    useCSSVariables: options.useCSSVariables,
  });

  // Textura tokens
  theme = createThemeWithoutDefaultMerge(theme, texturaTokens);

  // Create theme scoped styles that will apply to all elements within a <ThemeProvider />
  theme = createThemeWithoutDefaultMerge(theme, {
    // Styles that an apply to all elements under a theme provider (controled by "applyThemeScopedStyles" prop and defaults to true)
    // This will override any all global CSS of matching keys within a <ThemeProvider />
    // This can accept a JSS object, CSS string, or stringified CSS file
    themeScopedStyles: {
      color: theme.color.content.default,
      ...theme.typography.body.md,
      "*:focus-visible": {
        ...theme.focusRing,
      },
      a: {
        color: theme.textLink.secondary.color.enabled,
        textDecoration: theme.textLink.secondary.typography.enabled,
        cursor: "pointer",
        "&:hover": {
          color: theme.textLink.secondary.color.hover,
          textDecoration: theme.textLink.secondary.typography.hover,
        },
      },
      "*": {
        boxSizing: "border-box",
      },
      ".sr-only": {
        position: "absolute",
        width: "1px",
        height: "1px",
        padding: 0,
        margin: -1,
        overflow: "hidden",
        clip: "rect(0, 0, 0, 0)",
        whiteSpace: "nowrap",
        borderWidth: 0,
      },
    },
  });

  // Component variants
  theme = createThemeWithoutDefaultMerge(theme, {
    componentVariants: {
      Accordion: { default: {} },
      ActionHeader: { default: {} },
      Alert: { default: {} },
      AssetIcon: { default: {} },
      Avatar: { default: {} },
      AvatarStack: { default: {} },
      Badge: { default: {} },
      BarProgress: { default: {} },
      Breadcrumbs: { default: {} },
      Button: { default: {} },
      ButtonGroup: { default: {} },
      Card: { default: {} },
      Cell: { default: {} },
      Chart: { default: {} },
      Checkbox: { default: {} },
      CheckboxGroup: { default: {} },
      Chip: { default: {} },
      ChipBar: { default: {} },
      CircleProgress: { default: {} },
      CodeBlock: { default: {} },
      Combobox: { default: {} },
      Dialog: { default: {} },
      Divider: { default: {} },
      Drawer: { default: {} },
      EmptyState: { default: {} },
      Field: { default: {} },
      Float: { default: {} },
      Form: { default: {} },
      Header: { default: {} },
      IconButton: { default: {} },
      Image: { default: {} },
      InfoBlock: { default: {} },
      Input: { default: {} },
      LinkButton: { default: {} },
      List: { default: {} },
      MainNav: { default: {} },
      Menu: { default: {} },
      MenuItem: { default: {} },
      Modal: { default: {} },
      MultiSelect: { default: {} },
      Overlay: { default: {} },
      PageLayout: { default: {} },
      Pagination: { default: {} },
      Popover: { default: {} },
      RadioGroup: { default: {} },
      Search: { default: {} },
      SegmentedButton: { default: {} },
      Select: { default: {} },
      Skeleton: { default: {} },
      Slider: { default: {} },
      SplitButton: { default: {} },
      SvgIcon: { default: {} },
      Switch: { default: {} },
      TabBar: { default: {} },
      Table: { default: {} },
      Textarea: { default: {} },
      Toast: { default: {} },
      ToggleButton: { default: {} },
      Toolbar: { default: {} },
      Tooltip: { default: {} },
      ValueStepper: { default: {} },
      VerticalTabBar: { default: {} },
      RichText: { default: {} },
      InlineBadge: { default: {} },
      AI: { default: {} },
      AIDisclaimer: { default: {} },
      AIToolbar: { default: {} },
      SplitIconButton: { default: {} },
      DropdownIconButton: { default: {} },
      MainNavMenu: { default: {} },
      // THEMED COMPONENT VARIANTS
      // Do not remove the above comment, it is used by plop to add new component variants to theme (empty default to start)
    },
  });

  return theme;
};

const defaultTheme = getDefaultTheme();
export default defaultTheme;
